// ui-schedule.js — generated by the modularisation of index.html; see README for what lives where.
import { t } from './i18n.js';
import { S } from './state.js';
import { DAYS, WA_ICON_SMALL, todayKey } from './constants.js';
import { activeDeviation, alreadyGrouped, carsCountFor, computeDepartureTime, effectiveCars, eligibleDrivers, fam, famTime, girlName, girlsFor, groupsFor, planOptions, seats, timeToMinutes, tripReserveIds, unplacedFor } from './rides.js';
import { dayUp, weekRangeLabel } from './dates.js';
import { dirLabelHtml, esc, hapticTap, lastUpdateFooter, openSheet, phIcon, setStatus, showToast } from './ui-common.js';
import { timeChangesCardHtml, updateTimeChangesBadge, wireTimeChangesCard } from './ui-beheer.js';
import { goToWijzigen } from './ui-myweek.js';
import { myLinkedFamilyId, normalizePhone } from './coordinator.js';
import { driverAskText, reserveAskText } from './message-texts.js';
import { createGroupCustom, db, recordLastUpdate, useOption } from './data.js';

export function renderSchedule(){
  const box=document.getElementById('tab-schedule');
  if(!box) return;
  const mode = S.roosterMode;
  const pillsHtml = DAYS.map(([k,label])=>{
    const carCount = carsCountFor(k,mode);
    const unplaced = unplacedFor(k,'heen',mode).length + unplacedFor(k,'terug',mode).length;
    const isActive = k===S.scheduleDay;
    return `<button type="button" class="daypill ${isActive?'active':''}" data-schedday="${k}" aria-pressed="${isActive}" aria-label="${label}, ${carCount} ritten${unplaced? t('schedule.niet_ingedeeld_2', { p1: unplaced }):''}">
      <span class="daypillTop">${dayUp(k)}</span>
      <span class="daypillSub">${carCount} ${t('schedule.rit')}${carCount===1?'':'ten'}</span>
      ${k===todayKey? t('schedule.span_class_daypilltoday_aria_hidden') : ''}
      ${unplaced? `<span class="daypillAlert" aria-hidden="true">${unplaced}</span>` : ''}
    </button>`;
  }).join('');
  const label = DAYS.find(([k])=>k===S.scheduleDay)[1];
  const segHtml = `<div class="segmented" role="group" aria-label="${t('schedule.welk_rooster')}">
      <button type="button" data-rmode="week" class="${mode==='week'?'active':''}" aria-pressed="${mode==='week'}">${t('schedule.deze_week')}</button>
      <button type="button" data-rmode="standard" class="${mode==='standard'?'active':''}" aria-pressed="${mode==='standard'}">${t('schedule.standaardrooster')}</button>
    </div>
    <p class="muted" style="margin:-4px 2px 10px">${mode==='week'
      ? t('schedule.het_standaardrooster_met_de_wijzigingen', { p1: weekRangeLabel() })
      : t('schedule.het_vaste_rooster_elke_week', { p1: S.canEdit? t('schedule.tik_op_een_naam_om') : '' })}</p>`;
  const footer = mode==='week'
    ? lastUpdateFooter([S.lastUpdateRooster,S.lastUpdateDeviation].filter(Boolean).sort((a,b)=>(b.at||0)-(a.at||0))[0])
    : lastUpdateFooter(S.lastUpdateRooster);
  box.innerHTML = timeChangesCardHtml()
    + segHtml
    + `<div class="daypills" role="group" aria-label="${t('deviation.kies_een_dag')}">${pillsHtml}</div>`
    + renderDay(S.scheduleDay, label)
    + footer;
  document.querySelectorAll('[data-schedday]').forEach(b=>b.onclick=()=>{
    S.scheduleDay=b.dataset.schedday; hapticTap(); renderSchedule();
  });
  document.querySelectorAll('[data-rmode]').forEach(b=>b.onclick=()=>{
    S.roosterMode=b.dataset.rmode; S.pendingSwapRequest=null; hapticTap(); renderSchedule();
  });
  box.querySelectorAll('[data-gowijzig]').forEach(b=>b.onclick=()=>goToWijzigen(b.dataset.gowijzig));
  box.querySelectorAll('[data-gosugg]').forEach(b=>b.onclick=()=>{
    const el=document.getElementById('sugg-'+b.dataset.gosugg); const m=document.querySelector('main');
    if(el && m) m.scrollTop = el.getBoundingClientRect().top - m.getBoundingClientRect().top + m.scrollTop - 8;
  });
  wireTimeChangesCard();
  updateTimeChangesBadge();
  attachScheduleHandlers();
}

export function renderDay(day,label){
  const mode = S.roosterMode;
  const un = ['heen','terug'].map(d=>[d, unplacedFor(day,d,mode)]).filter(([,l])=>l.length);
  const total = un.reduce((n,[,l])=>n+l.length,0);
  const alertHtml = un.length? `<div class="unplacedAlert">
      <div class="ttl">${phIcon('warning')} ${total} ${t('schedule.niet_ingedeeld')}</div>
      ${un.map(([d,l])=>{
        const action = mode==='week'
          ? `<button type="button" class="btn small" data-gowijzig="${day}">${t('myweek.regelen')}</button>`
          : (S.canEdit? `<button type="button" class="btn small secondary" data-gosugg="${d}">${t('schedule.voorstellen')}</button>` : '');
        return `<div class="row"><span><strong>${d==='heen'?t('dir.heenShort'):t('dir.terugShort')}</strong>: ${l.map(([id])=>girlName(id)).join(', ')}</span>${action}</div>`;
      }).join('')}
    </div>` : '';
  return `<div class="daysection"><h3>${label}</h3>
    ${alertHtml}
    ${renderDirection(day,'heen')}
    ${renderDirection(day,'terug')}
  </div>`;
}

export function renderDirection(day,direction){
  return S.roosterMode==='week'? renderDirectionWeek(day,direction) : renderDirectionStandard(day,direction);
}

// ---------- Tap-to-WhatsApp (Rooster "Deze week") ----------
// wa.me wants the number in international format, digits only: 06-12345678 -> 31612345678.
export function waPhone(p){
  let d = normalizePhone(p);             // Dutch numbers normalised to 06…
  if(!d) return '';
  if(d.startsWith('00')) return d.slice(2);  // other international numbers: 0044… -> 44…
  if(d.startsWith('0')) return '31'+d.slice(1);
  return d;
}

// A parent's name as a WhatsApp link to their Tel.nr. 1 with a pre-filled message; plain text
// when no Tel.nr. 1 is set (nothing to link to).
export function waNameHtml(familyId, text){
  const f = fam(familyId);
  const name = esc(f.parentName||'?');
  const num = waPhone(f.parentPhone1);
  if(!num) return name;
  const href = 'https://wa.me/'+num+'?text='+encodeURIComponent(text);
  return `<a class="waLink" href="${esc(href)}" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp ${name}">${name}${WA_ICON_SMALL}</a>`;
}

// withWhatsApp: names become WhatsApp links asking to take over `askTime`'s ride ("Deze week").
export function tripReserveHtml(day,direction,cars,withWhatsApp,askTime){
  const ids = tripReserveIds(day,direction,cars);
  if(!ids.length) return '';
  const names = ids.map(id=> withWhatsApp? waNameHtml(id, reserveAskText(day,direction,askTime)) : esc(fam(id).parentName));
  return `<div class="tripReserve">${t('schedule.reserve')} ${names.join(', ')}</div>`;
}

export function neededTimesHtml(day,direction,girlIds){
  const times = girlIds.map(id=>famTime(id,day,direction)).filter(Boolean).sort();
  const range = `${times[0]||'?'}${times[times.length-1]!==times[0]?'–'+times[times.length-1]:''}`;
  return `<div class="subtime">${direction==='heen'? t('schedule.aankomst_alkmaar_nodig', { p1: range }) : t('schedule.klaar_om_op_te_halen', { p1: range })}</div>`;
}

export function driverLineHtml(driverId,myId,wa){
  if(!driverId) return `<div class="driver" style="color:var(--danger)">${phIcon('warning')} ${t('schedule.geen_chauffeur')}</div>`;
  if(myId && driverId===myId) return `<div class="driver me">${phIcon('car')} ${t('schedule.jij_rijdt')}</div>`;
  // wa = {day,time}: "Deze week" — the chauffeur's name opens WhatsApp to them.
  const name = wa? waNameHtml(driverId, driverAskText(wa.day, wa.time)) : esc(fam(driverId).parentName);
  return `<div class="driver">${phIcon('car')} ${t('schedule.chauffeur')} ${name}</div>`;
}

export function pillsHtml(girlIds,myId){
  return girlIds.map(id=>`<span class="pill${id===myId?' mine':''}">${girlName(id)}</span>`).join('');
}

// "Deze week": what actually runs this week — read-only; changes go through Wijzigen.
export function renderDirectionWeek(day,direction){
  const cars = effectiveCars(day,direction).filter(c=>(c.girlIds||[]).length);
  const dev = activeDeviation(day,direction);
  const myId = myLinkedFamilyId();
  const cardsHtml = cars.map((c,i)=>{
    const driver = c.driverFamilyId? fam(c.driverFamilyId) : null;
    const mineDriving = myId && c.driverFamilyId===myId;
    return `<div class="group confirmed${mineDriving?t('schedule.minedriving'):''}">
      <div class="rowflex" style="align-items:flex-start;gap:10px">
        <div class="rowflex" style="gap:10px;align-items:flex-start;flex:1">
          <span class="dayBadge accent">${i+1}</span>
          <div><div class="dir">${t('deviation.vertrek')}</div><div class="time">${esc(c.departureTime||'--:--')}</div></div>
        </div>
        ${driver? `<span class="capbadge">${c.girlIds.length}/${seats(driver)} ${t('schedule.plekken')}</span>` : ''}
      </div>
      ${neededTimesHtml(day,direction,c.girlIds)}
      <div>${pillsHtml(c.girlIds,myId)}</div>
      ${driverLineHtml(c.driverFamilyId,myId,{day,time:c.departureTime})}
    </div>`;
  }).join('') || `<p class="muted">${t('schedule.geen_ritten')}</p>`;
  // The ride a reserve is asked to take over: the one you drive, else your daughter's, else the first.
  const askCar = cars.find(c=>myId && c.driverFamilyId===myId) || cars.find(c=>myId && (c.girlIds||[]).includes(myId)) || cars[0];
  return `<div style="margin-bottom:10px">
    <div class="rowflex" style="justify-content:flex-start;gap:6px;flex-wrap:wrap">${dirLabelHtml(direction)}${dev? `<span class="changedTag">${phIcon('lightning')} ${t('schedule.gewijzigd')}</span>`:''}</div>
    ${cardsHtml}
    ${tripReserveHtml(day,direction,cars,true,askCar&&askCar.departureTime)}
  </div>`;
}

// "Standaardrooster": the fixed schedule; the coordinator edits it here.
export function renderDirectionStandard(day,direction){
  const grps = groupsFor(day,direction);
  const grouped = alreadyGrouped(day,direction);
  const ungrouped = girlsFor(day,direction).filter(([id])=>!grouped.has(id));
  const myId = myLinkedFamilyId();

  const groupHtml = grps.map(([gid,g],gi)=>{
    const times = (g.girlIds||[]).map(id=>famTime(id,day,direction)).filter(Boolean).sort();
    const departureFallback = direction==='terug' ? times[times.length-1] : times[0];
    const departure = g.departureTime || departureFallback || '--:--';
    const driver = g.driverFamilyId? fam(g.driverFamilyId):null;
    const otherGroups = grps.filter(([oid])=>oid!==gid);
    const mineDriving = myId && g.driverFamilyId===myId;
    // Only offer drivers who aren't already committed to another car this same trip —
    // prevents double-booking instead of fixing it up after the fact.
    const busyElsewhere = new Set(otherGroups.map(([,og])=>og.driverFamilyId).filter(Boolean));
    const eligible = eligibleDrivers(day,direction,g.girlIds.length).filter(([id])=>!busyElsewhere.has(id));
    const driverOptions = `<option value="" disabled ${!g.driverFamilyId?'selected':''}>${t('schedule.kies_chauffeur')}</option>` + eligible.map(([id,f])=>`<option value="${id}" ${id===g.driverFamilyId?'selected':''}>${esc(f.parentName)} (${seats(f)} ${t('beheer.pl')}</option>`).join('');
    const timeHtml = S.canEdit
      ? `<input type="time" class="timeBig" data-deptime="${gid}" value="${departure!=='--:--'?departure:''}" aria-label="Vertrektijd auto ${gi+1}">`
      : `<div class="time">${departure}</div>`;
    const pills = g.girlIds.map(id=>{
      const cls = `pill${id===myId?' mine':''}`;
      return (S.canEdit && otherGroups.length)
        ? `<button type="button" class="${cls}" data-movepill="${gid}|${id}" aria-label="${t('schedule.verplaats',{p1:girlName(id)})}" aria-haspopup="dialog">${girlName(id)}</button>`
        : `<span class="${cls}">${girlName(id)}</span>`;
    }).join('');
    const driverHtml = S.canEdit
      ? `<div class="driver">${phIcon('car')}<select data-swap="${gid}" aria-label="Chauffeur auto ${gi+1}">${driverOptions}</select></div>`
      : driverLineHtml(g.driverFamilyId,myId);
    return `<div class="group confirmed${mineDriving?t('schedule.minedriving'):''}" data-gid="${gid}">
      <div class="rowflex" style="align-items:flex-start;gap:10px">
        <div class="rowflex" style="gap:10px;align-items:flex-start;flex:1">
          <span class="dayBadge accent">${gi+1}</span>
          <div><div class="dir">${t('deviation.vertrek')}</div>${timeHtml}</div>
        </div>
        <div style="display:flex;align-items:center;gap:6px">
          ${driver? `<span class="capbadge">${g.girlIds.length}/${seats(driver)} ${t('schedule.plekken')}</span>` : ''}
          ${S.canEdit? `<button type="button" class="iconbtn danger" data-delgroup="${gid}" aria-label="Verwijder auto ${gi+1}" title="${t('schedule.verwijder_auto')}">${phIcon('trash')}</button>` : ''}
        </div>
      </div>
      ${neededTimesHtml(day,direction,g.girlIds)}
      <div>${pills}</div>
      ${driverHtml}
      ${S.pendingSwapRequest && S.pendingSwapRequest.toGid===gid? `<div class="dayFormCard" style="margin-top:8px;border-color:var(--warn)">
          <p class="fitbad" style="margin:0 0 6px">${t('schedule.geen_plek_meer_in_deze')}${g.girlIds.length}/${seats(driver)} ${t('schedule.bezet_wil_je')} ${girlName(S.pendingSwapRequest.girlId)} ${t('schedule.wisselen_met_een_andere_passagier')}</p>
          <select id="swapPickGirl" aria-label="${t('schedule.wissel_met_welke_passagier')}">${g.girlIds.map(id=>`<option value="${id}">${esc(fam(id).girlName||fam(id).parentName||id)}</option>`).join('')}</select>
          <div class="rowflex" style="margin-top:8px;gap:6px">
            <button type="button" class="btn small" data-swapconfirm="${gid}">${t('schedule.wissel')}</button>
            <button type="button" class="btn small secondary" data-swapcancel="${gid}">${t('common.annuleren')}</button>
          </div>
        </div>`:''}
    </div>`;
  }).join('') || `<p class="muted">${t('schedule.nog_geen_ritten_ingepland')}</p>`;

  let suggestHtml = '';
  let pickerHtml = '';
  if(S.canEdit && ungrouped.length){
    const n = ungrouped.length;
    const names = ungrouped.map(([id])=>girlName(id)).join(', ');
    // 1) Room in cars that already run this trip (and the times fit): usually the simplest fix.
    //    Each not-yet-placed girl goes to the car with a free seat where her time fits best.
    const gapLimit = (S.settings.gapThresholdHours||3)*60;
    const tMin = id=>timeToMinutes(famTime(id,day,direction));
    const pool = grps.map(([gid,g],gi)=>({gid, num:gi+1, driverId:g.driverFamilyId, ids:[...g.girlIds], cap:g.driverFamilyId? seats(fam(g.driverFamilyId)) : 0}));
    const placements = [];
    [...ungrouped].sort((a,b)=>(tMin(a[0])||0)-(tMin(b[0])||0)).forEach(([id])=>{
      let best=null;
      pool.forEach(c=>{
        if(!c.driverId || c.ids.length>=c.cap) return;
        const mins=[...c.ids,id].map(tMin).filter(v=>v!=null);
        const spread=Math.max(...mins)-Math.min(...mins);
        if(spread<=gapLimit && (!best || spread<best.spread)) best={c,spread};
      });
      if(best){ best.c.ids.push(id); placements.push({girlId:id, gid:best.c.gid}); }
    });
    const addOpts = [];
    if(placements.length===n){
      const touched = pool.filter(c=>placements.some(pl=>pl.gid===c.gid));
      addOpts.push({kind:'add', placements, touched: touched.map(c=>({gid:c.gid, num:c.num, driverId:c.driverId, ids:c.ids, cap:c.cap, dep:computeDepartureTime(day,direction,c.ids)}))});
    }
    // 2) New car(s), from the planning engine.
    // (options that would give a parent a second car on this same trip are left out)
    const drivingThisTrip = new Set(grps.map(([,g])=>g.driverFamilyId).filter(Boolean));
    const options = planOptions(day,direction,ungrouped).filter(o=>!o.assignment.some(a=>drivingThisTrip.has(a.driverId)));
    const all = [...addOpts, ...options.map(o=>({kind:'new', ...o}))];
    window.__planOptions = window.__planOptions||{};
    window.__planOptions[day+'|'+direction] = all;
    const intro = `<p class="muted" style="margin:10px 0 4px" id="sugg-${direction}">${n===1? t('schedule.nog_niet_ingedeeld', { p1: names }) : t('schedule.nog_niet_ingedeeld_2', { p1: n, p2: names })} ${t('schedule.voorstellen_2')}</p>`;
    if(all.length){
      suggestHtml = intro + all.map((opt,i)=>{
        const title = opt.kind==='add'
          ? (opt.touched.length===1? t('schedule.toevoegen_aan_auto', { p1: opt.touched[0].num, p2: esc(fam(opt.touched[0].driverId).parentName) }) : t('schedule.toevoegen_aan_bestaande_auto_s'))
          : t('schedule.nieuwe_auto', { p1: opt.label });
        const sub = opt.kind==='add'
          ? opt.touched.map(c=>t('schedule.auto_regel',{p1:c.num,p2:c.ids.map(id=>girlName(id)).join(', '),p3:c.ids.length,p4:c.cap,p5:c.dep})).join(' · ')
          : opt.assignment.map(a=>`${esc(fam(a.driverId).parentName)}: ${a.girlIds.map(id=>girlName(id)).join(', ')} (${a.girlIds.length}/${seats(fam(a.driverId))} pl.)`).join(' · ');
        return `<div class="group suggestion${i===0?t('schedule.primary'):''}">
          <div class="fitok">${i===0?t('schedule.span_class_badge_rec_aanbevolen'):''}${t('schedule.optie')} ${i+1}: ${title}</div>
          <div class="subtime">${sub}</div>
          <button type="button" class="btn small${i===0?'':t('schedule.secondary')}" data-useoption="${day}|${direction}|${i}" style="margin-top:8px">${t('schedule.gebruik_deze_optie')}</button>
        </div>`;
      }).join('');
    } else {
      suggestHtml = intro + `<div class="group warning"><div class="fitbad">${phIcon('warning')} ${t('schedule.geen_enkele_chauffeur_scombinatie_heeft')} ${n===1?t('schedule.deze_meid'):t('schedule.deze_n_meiden',{p1:n})}.</div></div>`;
    }
    const ungroupedSorted = [...ungrouped].sort((a,b)=>{
      const ta=timeToMinutes(a[1].schedule[day][direction]), tb=timeToMinutes(b[1].schedule[day][direction]);
      if(ta!==tb) return ta-tb;
      return (a[1].girlName||'').localeCompare(b[1].girlName||'');
    });
    pickerHtml = `
    <div class="group" style="border-style:dashed">
      <h3 style="margin-bottom:6px">${t('schedule.aangepaste_combinatie')}</h3>
      ${ungroupedSorted.map(([id,f])=>`<div class="girlchk"><label style="margin:0;flex:1"><input type="checkbox" class="girlpick" value="${id}"> ${esc(f.girlName||f.parentName)} — ${f.schedule[day][direction]}</label></div>`).join('')}
      <button type="button" class="btn small secondary" data-makegroup="${day}|${direction}" style="margin-top:8px">${t('schedule.nieuwe_auto_met_deze_meiden')}</button>
    </div>`;
  } else if(S.canEdit){
    pickerHtml = `<p class="muted">${t('schedule.iedereen_is_ingedeeld')}</p>`;
  }
  const dev = activeDeviation(day,direction);
  const cars = grps.map(([,g])=>g);
  return `<div style="margin-bottom:10px">
    <div class="rowflex" style="justify-content:flex-start;gap:6px;flex-wrap:wrap">${dirLabelHtml(direction)}${dev? `<span class="changedTag" title="${t('schedule.zie_deze_week')}">${phIcon('lightning')} ${t('schedule.deze_week_gewijzigd')}</span>`:''}</div>
    ${groupHtml}
    ${tripReserveHtml(day,direction,cars)}
    ${suggestHtml}${pickerHtml}
  </div>`;
}

// Move a passenger to another car of the same trip (Standaardrooster). A full destination car
// offers a swap on that car's own card instead of just refusing.
export async function moveGirlToGroup(gid, girlId, toGid){
  const from=S.groups[gid], to=S.groups[toGid];
  if(!from||!to) return;
  if(to.driverFamilyId){
    const toSeats = seats(fam(to.driverFamilyId));
    if(to.girlIds.length >= toSeats){
      S.pendingSwapRequest = {fromGid:gid, girlId, toGid};
      renderSchedule();
      const card=document.querySelector(`[data-gid="${toGid}"]`); if(card) card.scrollIntoView({block:'center'});
      return;
    }
  }
  try{
    const newFrom=from.girlIds.filter(id=>id!==girlId);
    const newTo=[...to.girlIds, girlId];
    // Both cars' departure times depend on who's actually in them — recalculate both.
    const fromDeparture = computeDepartureTime(from.day, from.direction, newFrom);
    const toDeparture = computeDepartureTime(to.day, to.direction, newTo);
    if(newFrom.length){ await db.doc("groups/"+gid).update({girlIds:newFrom, departureTime: fromDeparture}); }
    else { await db.doc("groups/"+gid).delete(); }
    await db.doc("groups/"+toGid).update({girlIds:newTo, departureTime: toDeparture});
    recordLastUpdate('Rooster');
    showToast(girlName(girlId).replace(/&amp;/g,'&')+t('schedule.verplaatst'));
  }catch(e){showToast(t('schedule.verplaatsen_mislukt')+(e&&e.message||e));}
}

export function openMoveSheet(gid, girlId){
  const g=S.groups[gid]; if(!g) return;
  const trip = groupsFor(g.day,g.direction);
  const items = trip.map(([oid,og],i)=>[oid,og,i]).filter(([oid])=>oid!==gid).map(([oid,og,i])=>{
    const drv = og.driverFamilyId? fam(og.driverFamilyId) : null;
    const cap = drv? seats(drv) : null;
    const full = cap!=null && og.girlIds.length>=cap;
    return {
      label: t('schedule.auto_label',{p1:i+1,p2:drv? esc(drv.parentName) : t('schedule.geen_chauffeur_2')}),
      sub: t('schedule.vertrek', { p1: esc(og.departureTime||'--:--'), p2: cap!=null? t('schedule.plekken_2', { p1: og.girlIds.length, p2: cap }):'', p3: full? t('schedule.vol_je_kunt_wisselen'):'' }),
      onClick: ()=>moveGirlToGroup(gid, girlId, oid)
    };
  });
  openSheet(t('schedule.verplaats',{p1:girlName(girlId)}), t('schedule.kies_een_andere_auto', { p1: g.direction==='heen'?t('dir.heenShort'):t('dir.terugShort'), p2: DAYS.find(([k])=>k===g.day)[1] }), items);
}

export function attachScheduleHandlers(){
 try{
  document.querySelectorAll('[data-makegroup]').forEach(btn=>btn.onclick=async ()=>{
    const [day,direction]=btn.dataset.makegroup.split('|');
    const box=btn.closest('.group');
    const picked=[...box.querySelectorAll('.girlpick:checked')].map(c=>c.value);
    await createGroupCustom(day,direction,picked);
  });
  document.querySelectorAll('[data-useoption]').forEach(btn=>btn.onclick=async ()=>{
    const [day,direction,idxStr]=btn.dataset.useoption.split('|');
    const opts=(window.__planOptions||{})[day+'|'+direction]||[];
    const opt=opts[+idxStr];
    if(!opt) return;
    if(opt.kind==='add'){
      // Add the not-yet-placed girls to existing cars (re-read each car, in case it changed meanwhile).
      try{
        const byGid={};
        opt.placements.forEach(pl=>{ (byGid[pl.gid]=byGid[pl.gid]||[]).push(pl.girlId); });
        for(const [gid,add] of Object.entries(byGid)){
          const g=S.groups[gid]; if(!g){ showToast(t('schedule.een_van_de_auto_s')); return; }
          const ids=[...new Set([...g.girlIds, ...add])];
          await db.doc("groups/"+gid).update({girlIds:ids, departureTime:computeDepartureTime(day,direction,ids)});
        }
        recordLastUpdate('Rooster'); showToast(t('beheer.toegevoegd'));
      }catch(e){ showToast(t('schedule.toevoegen_mislukt')+(e&&e.message||e)); }
    } else {
      await useOption(day,direction,opt.assignment);
    }
  });
  document.querySelectorAll('[data-delgroup]').forEach(btn=>btn.onclick=async ()=>{
    try{ await db.doc("groups/"+btn.dataset.delgroup).delete(); recordLastUpdate('Rooster'); }catch(e){showToast(t('beheer.verwijderen_mislukt')+(e&&e.message||e));}
  });
  document.querySelectorAll('[data-swap]').forEach(sel=>sel.onchange=async ()=>{
    const gid=sel.dataset.swap; const g=S.groups[gid]; if(!g)return;
    const newDriver=sel.value;
    try{
      await db.doc("groups/"+gid).update({driverFamilyId:newDriver});
      const siblings = groupsFor(g.day,g.direction).filter(([oid,og])=>oid!==gid && og.driverFamilyId===newDriver);
      for(const [oid,og] of siblings){
        const usedElsewhere = new Set(groupsFor(g.day,g.direction).filter(([xid])=>xid!==oid).map(([xid,xg])=>xg.driverFamilyId).filter(Boolean));
        usedElsewhere.add(newDriver);
        const alt = eligibleDrivers(g.day,g.direction,og.girlIds.length).map(([id])=>id).find(id=>!usedElsewhere.has(id));
        await db.doc("groups/"+oid).update({driverFamilyId: alt||null});
      }
      showToast(siblings.length? t('schedule.chauffeur_gewisseld_dubbele_boeking_automatisch') : t('schedule.chauffeur_gewisseld'));
      recordLastUpdate('Rooster');
    }catch(e){showToast(t('schedule.wisselen_mislukt')+(e&&e.message||e));}
  });
  document.querySelectorAll('[data-deptime]').forEach(inp=>inp.onchange=async ()=>{
    const gid=inp.dataset.deptime;
    try{ await db.doc("groups/"+gid).update({departureTime:inp.value}); recordLastUpdate('Rooster'); }catch(e){showToast(t('schedule.aanpassen_mislukt')+(e&&e.message||e));}
  });
  document.querySelectorAll('[data-movepill]').forEach(btn=>btn.onclick=()=>{
    const [gid,girlId]=btn.dataset.movepill.split('|');
    hapticTap(); openMoveSheet(gid,girlId);
  });
  document.querySelectorAll('[data-swapconfirm]').forEach(btn=>btn.onclick=async ()=>{
    if(!S.pendingSwapRequest) return;
    const swapSel=document.getElementById('swapPickGirl');
    const swapWithId = swapSel && swapSel.value;
    if(!swapWithId){ showToast(t('schedule.kies_wie_je_wilt_wisselen')); return; }
    const {fromGid, girlId, toGid} = S.pendingSwapRequest;
    const from=S.groups[fromGid], to=S.groups[toGid];
    if(!from||!to){ S.pendingSwapRequest=null; renderSchedule(); return; }
    const newFrom = from.girlIds.filter(id=>id!==girlId).concat([swapWithId]);
    const newTo = to.girlIds.filter(id=>id!==swapWithId).concat([girlId]);
    try{
      const fromDeparture = computeDepartureTime(from.day, from.direction, newFrom);
      const toDeparture = computeDepartureTime(to.day, to.direction, newTo);
      await db.doc("groups/"+fromGid).update({girlIds:newFrom, departureTime:fromDeparture});
      await db.doc("groups/"+toGid).update({girlIds:newTo, departureTime:toDeparture});
      recordLastUpdate('Rooster');
      showToast(t('schedule.gewisseld'));
    }catch(e){ showToast(t('schedule.wisselen_mislukt')+(e&&e.message||e)); }
    S.pendingSwapRequest=null;
    renderSchedule();
  });
  document.querySelectorAll('[data-swapcancel]').forEach(btn=>btn.onclick=()=>{ S.pendingSwapRequest=null; renderSchedule(); });
 }catch(e){ setStatus(t('schedule.fout_bij_koppelen_roosterknoppen')+(e&&e.message||e), true); }
}
